// Dead Ground service worker — makes the game work offline once it has loaded one time.
// Generated by tools-make-sw.py from sw.template.js; the cache name changes with every game version.
const CACHE = 'deadground-0.22';
const FILES = [
  './',
  'index.html',
  'manifest.webmanifest',
  'css/style.css',
  'js/animals.js',
  'js/audio.js',
  'js/boss.js',
  'js/building.js',
  'js/character.js',
  'js/characters.js',
  'js/crafting.js',
  'js/daynight.js',
  'js/effects.js',
  'js/factions.js',
  'js/gather.js',
  'js/input.js',
  'js/install.js',
  'js/interact.js',
  'js/interiors.js',
  'js/items.js',
  'js/locations.js',
  'js/main.js',
  'js/missions.js',
  'js/npc.js',
  'js/player.js',
  'js/settings.js',
  'js/state.js',
  'js/storage.js',
  'js/story.js',
  'js/style.js',
  'js/survival.js',
  'js/tutorial.js',
  'js/ui.js',
  'js/util.js',
  'js/vehicles.js',
  'js/weather.js',
  'js/world.js',
  'js/zombies.js',
  'lib/three.module.min.js',
  'icons/apple-touch-icon.png',
  'icons/favicon-32.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/maskable-512.png'
];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('deadground-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('message', e => { if (e.data === 'update') self.skipWaiting(); });
self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.hostname === 'api.github.com') return;          // saves always go to GitHub live
  if (url.hostname.includes('fonts.g')) {                                          // fonts: use cache, refresh in background
    e.respondWith(caches.open(CACHE).then(async c => { const hit = await c.match(req); const net = fetch(req).then(r => { c.put(req, r.clone()); return r; }).catch(() => hit); return hit || net; }));
    return;
  }
  if (url.origin !== location.origin) return;
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(r => { if (r.ok) caches.open(CACHE).then(c => c.put(req, r.clone())); return r; })));
});
